svg.script:
//
    import Palette from '../main.js'
      const palette = new Palette('protosite-palette', {})

      /**
      * Define monochrome colors via register CSS properties
      */
      {
      let { black, gray, white } = palette

      CSS.registerProperty({
      name: "--clr-black",
      syntax: "<color>",
      inherits: false,
      initialValue: black.toString(),
      })
      CSS.registerProperty({
      name: "--clr-gray",
      syntax: "<color>",
      inherits: false,
      initialValue: gray.toString(),
      })
      CSS.registerProperty({
      name: "--clr-white",
      syntax: "<color>",
      inherits: false,
      initialValue: white.toString(),
      })
      }
      //
